import{_ as t,c as o,b as n,o as a}from"./app-BRWvUhL_.js";const r={};function l(s,e){return a(),o("div",null,e[0]||(e[0]=[n('<p>In this section of the blog, you’ll find everything related to the admin account. This includes all the essential settings and information specific to the admin’s configuration and control.</p><p>From here, the admin can enter the business email, set the currency for the shop, choose the weight unit for products, and much more.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2017/11/Configuration-_-Admin.jpg" alt="General configuration Multivendor Marketplace for Shopify by Webkul"></p><p>To know about the <strong>Configuration Updates</strong>, Kindly refer: <a href="https://webkul.com/blog/configuration-updates-multi-vendor-marketplace-for-shopify/" target="_blank" rel="noopener noreferrer">https://webkul.com/blog/configuration-updates-multi-vendor-marketplace-for-shopify/</a></p><h3 id="minimum-purchase-amount-for-orders" tabindex="-1"><a class="header-anchor" href="#minimum-purchase-amount-for-orders"><span>Minimum Purchase Amount for Orders</span></a></h3><p>You can now allow sellers to set a minimum purchase amount for orders. That is, using this feature, you can restrict purchases for customers if the checkout condition is not satisfied.</p><p>The customer can proceed to checkout only when the cart amount is greater than or equal to the minimum purchase amount set by the seller.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/Configuration-Admin-2-1.png" alt="MULTIVENDOR MARKETPLACE"></p><p>All you need to do is just visit the <strong>General Configuration</strong> section of the app and enable the tab.</p><p>So, as soon as you enable the “<strong>Minimum Purchase Amount</strong>” tab, the same will reflect at the seller side in the General Configuration menu.</p><p>That is, sellers can set a minimum amount required for the customers while purchasing products.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/General-Configuration-Seller-•-Multivendor-MarketPlace.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Now, only when the cart amount reaches the “minimum purchase amount”, the customers can proceed for checkout.</p><p>Else, the customer can either add more products to cart or increase product quantity so that the cart amount can reach the minimum purchase amount &amp; he can easily proceed for checkout.</p><h3 id="c2c-convert-your-customers-to-sellers" tabindex="-1"><a class="header-anchor" href="#c2c-convert-your-customers-to-sellers"><span>C2C: CONVERT YOUR CUSTOMERS TO SELLERS</span></a></h3><p>Take advantage of the new functionality of converting your customers into sellers with ease.</p><p>All you need to do is add the following code into the <strong>customer/account.liquid</strong> theme page to display the <strong>“Seller Portal”</strong> button on the customer’s account page.</p><p>To paste the below given, follow the below process:</p><p><a class="btn btn--small wk\\_c2c\\_marketplace" target="\\_blank" href="https://sp-seller.webkul.com/?p=c2c\\_marketplace\\_process&amp;customer\\_id={{customer.id}}&amp;shop={{shop.permanent\\_domain}}" style="display:none;float:right;">Seller Portal</a></p><ul><li>Go To Themes.</li><li>Click on Customize Theme button.</li><li>Further, click on the Edit Code button.</li><li>Select <strong>customer/account.liquid</strong> file from the templates.</li><li>Paste the code.</li><li>Click on save.</li></ul><p>Once it is done, you will have to enable <strong>C2C Marketplace</strong> button from <strong>General Configuration</strong> &gt;&gt;&gt; Activate this feature.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/13-10.png" alt="MULTIVENDOR MARKETPLACE"></p><p>**The functionality of C2C Marketplace:-<br> **Enabling this feature, you can allow the buyers to convert into the sellers.</p><p>As soon as you enable this feature, you will have a few options to choose when you want to create customers:-<br> -At the time of sign up<br> -At the time of seller approval<br> -Don’t need to create customers.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Screenshot6.png" alt="MULTIVENDOR MARKETPLACE"></p><p><strong>If the 1st option “At the time of sign up” is enabled:-</strong><br> The sellers will be added as a customer as soon as they get registered to the marketplace.</p><p><strong>In case the 2nd option “At the time of seller approval” is enabled:-</strong></p><p>If a seller registers on the marketplace, the &#39;Auto Approve Seller&#39; tab should be disabled. This action will ensure that sellers are added as customers to the admin’s Shopify store</p><p>**Don’t need to create customers.<br> **Select this option if you don’t want to add the registered sellers as customers.</p><p>On the <strong>front end</strong>, customers will get a button name as seller portal to become a seller.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/04/s8-1200x531.png" alt="s8"></p><p>After clicking on the seller portal button it will redirect you to the terms and conditions page set by the store owner.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/04/s9.png" alt="s9"></p><p>If the customer tick and click on submit tab it will redirect you to the seller portal but customer click on the cancel tab it will redirect to the previous page.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/04/s12-1200x551.png" alt="s12"></p><h3 id="minimum-purchase-amount-for-orders-1" tabindex="-1"><a class="header-anchor" href="#minimum-purchase-amount-for-orders-1"><span>Minimum Purchase Amount for Orders</span></a></h3><p>You can now allow sellers to set a minimum purchase amount for orders. That is, using this feature, you can restrict purchases for customers if the checkout condition is not satisfied.</p><p>The customer can proceed to checkout only when the cart amount is greater than or equal to the minimum purchase amount set by the seller.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/Configuration-Admin-2-1.png" alt="MULTIVENDOR MARKETPLACE"></p><p>All you need to do is just visit the <strong>General Configuration</strong> section of the app and enable the tab.</p><p>So, as soon as you enable the “<strong>Minimum Purchase Amount</strong>” tab, the same will reflect at the seller side in the General Configuration menu.</p><p>That is, sellers can set a minimum amount required for the customers while purchasing products.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/General-Configuration-Seller-•-Multivendor-MarketPlace.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Now, only when the cart amount reaches the “minimum purchase amount”, the customers can proceed for checkout.</p><p>Else, the customer can either add more products to cart or increase product quantity so that the cart amount can reach the minimum purchase amount &amp; he can easily proceed for checkout.</p><p>#Let’s understand it with an instance</p><p>Price of Product A: $500<br> Price of Product B: $1000<br> Minimum Purchase Amount: $600*</p><ul><li>Customer A adds Product A to Cart worth $500– <strong>FAILED TO CHECKOUT</strong> (as Product Price($500) &lt; Minimum Purchase Amount ($600)</li><li>Customer B adds Product B to Cart worth $1000–<strong>CHECKOUT</strong> <strong>SUCCESSFULLY</strong> (as Product Price($1000) &gt; Minimum Purchase Amount ($600)</li></ul><p>In order to display the checkout conditions on the Cart page, you need to add the codes to the suggested liquid files (as shown in the screenshot).</p><p>So, go to Multi-vendor Admin Panel and then</p><p>Configuration &gt;&gt;Instruction for Marketplace &gt;&gt; Scroll down to get the codes for “Seller’s Minimum Purchase Amount for Orders” &gt;&gt; Copy the code from there &amp; add it to the instructed liquid files.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/Instructions-Admin.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Once you add the codes to their respective liquid files, this will be the visibility of the cart page (Refer below screenshots).</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/06/Your-Shopping-Cart-–-Demo-Shop-1135x1024.png" alt="MULTIVENDOR MARKETPLACE"></p><p>In short, if the cart amount is equal or greater than the minimum purchase amount, the customer can proceed for checkout.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/06/Your-Shopping-Cart-–-Demo-Shop-1-1135x1024.png" alt="MULTIVENDOR MARKETPLACE"></p><h3 id="change-the-copyright-label-of-the-app-footer" tabindex="-1"><a class="header-anchor" href="#change-the-copyright-label-of-the-app-footer"><span>Change the Copyright label of the app footer</span></a></h3><p>Now, you can change the copyright label of the app footer, for this visit-</p><p>App admin panel&gt;&gt;Configuration&gt;&gt;General Configuration</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/09/screenshot_1695927184457-1200x590.png" alt="screenshot_1695927184457"></p><p><strong>NOTE</strong>- This feature is available only in the PRO plan of the app.</p><h3 id="default-currency-symbol" tabindex="-1"><a class="header-anchor" href="#default-currency-symbol"><span>Default Currency Symbol</span></a></h3><p>This feature allows the admin to replace the default currency symbol displayed in the seller panel with a custom text/symbol of the admin&#39;s choice wherever the currency symbol appears.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/02/currency2-1200x696.webp" alt="Currency"></p><p>To configure the default currency symbol for your sellers, the Admin needs to navigate to:<br> Admin Dashboard&gt;General Configuration&gt;Enable Custom Currency Symbol&gt;Enter your Currency Symbol&gt;Save changes.</p><h3 id="google-translation-for-admin-and-seller-panel" tabindex="-1"><a class="header-anchor" href="#google-translation-for-admin-and-seller-panel"><span>Google Translation For Admin And Seller Panel</span></a></h3><p>We’ve added a new feature in our Multivendor Marketplace app that allows you to translate both the Admin and Seller panels using Google Translate.</p><p>With just one configuration, you can choose whether you want to translate only the Admin panel, only the Seller panel, or both.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/translate-1200x575.webp" alt="configuration-google-translate"></p><p>To enable this feature, simply navigate to <strong>Admin Panel &gt;&gt; Configuration &gt;&gt; General Configuration</strong> and choose your preferred option.</p><p>Once enabled, a Google Translate dropdown will appear at the top-right corner of the selected panel(s).</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/dropdown-1200x943.webp" alt="configuration-translation-dropdown"></p><p>From there, you can choose your preferred language, and the entire panel will be translated instantly.</p><p>This makes it easier for admins and sellers from different regions to use the app in their own language, offering a more user-friendly and accessible experience.</p><p><strong>Note</strong> : <strong>This feature is not compatible with the Weglot Translation featured app. If Weglot is enabled, this feature will not function as expected.</strong></p><h3 id="google-translation-for-admin-and-seller-panel-1" tabindex="-1"><a class="header-anchor" href="#google-translation-for-admin-and-seller-panel-1"><span>Google Translation For Admin And Seller Panel</span></a></h3><p>We’ve added a new feature in our Multivendor Marketplace app that allows you to translate both the Admin and Seller panels using Google Translate.</p><p>With just one configuration, you can choose whether you want to translate only the Admin panel, only the Seller panel, or both.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/translate-1200x575.webp" alt="configuration-google-translate"></p><p>To enable this feature, simply navigate to <strong>Admin Panel &gt;&gt; Configuration &gt;&gt; General Configuration</strong> and choose your preferred option.</p><p>Once enabled, a Google Translate dropdown will appear at the top-right corner of the selected panel(s).</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/dropdown-1200x943.webp" alt="configuration-translation-dropdown"></p><p>From there, you can choose your preferred language, and the entire panel will be translated instantly.</p><p>This makes it easier for admins and sellers from different regions to use the app in their own language, offering a more user-friendly and accessible experience.</p><p><strong>Note</strong> : <strong>This feature is not compatible with the Weglot Translation featured app. If Weglot is enabled, this feature will not function as expected.</strong></p>',85)]))}const c=t(r,[["render",l]]),p=JSON.parse('{"path":"/classic/configuration/general-configration.html","title":"Multivendor Marketplace:General configuration","lang":"en-US","frontmatter":{"title":"Multivendor Marketplace:General configuration","description":"Learn about General configuration.","date":"2025-06-25T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Minimum Purchase Amount for Orders","slug":"minimum-purchase-amount-for-orders","link":"#minimum-purchase-amount-for-orders","children":[]},{"level":3,"title":"C2C: CONVERT YOUR CUSTOMERS TO SELLERS","slug":"c2c-convert-your-customers-to-sellers","link":"#c2c-convert-your-customers-to-sellers","children":[]},{"level":3,"title":"Minimum Purchase Amount for Orders","slug":"minimum-purchase-amount-for-orders-1","link":"#minimum-purchase-amount-for-orders-1","children":[]},{"level":3,"title":"Change the Copyright label of the app footer","slug":"change-the-copyright-label-of-the-app-footer","link":"#change-the-copyright-label-of-the-app-footer","children":[]},{"level":3,"title":"Default Currency Symbol","slug":"default-currency-symbol","link":"#default-currency-symbol","children":[]},{"level":3,"title":"Google Translation For Admin And Seller Panel","slug":"google-translation-for-admin-and-seller-panel","link":"#google-translation-for-admin-and-seller-panel","children":[]},{"level":3,"title":"Google Translation For Admin And Seller Panel","slug":"google-translation-for-admin-and-seller-panel-1","link":"#google-translation-for-admin-and-seller-panel-1","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":2,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"},{"hash":"769a52a9d6ea585a51f97bd9091014ed466fba2c","time":1751543091000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"classic/configuration/general-configration.md"}');export{c as comp,p as data};
